document.addEventListener("click", function(e){
  const topbar = document.querySelector(".topbar");
  const menu = document.querySelector(".topbar");
  if(!topbar) return;

  const isOpen = topbar.classList.contains("menu-open");
  if(!isOpen) return;

  const clickedInside = e.target.closest(".topbar");
  if(!clickedInside){
    topbar.classList.remove("menu-open");
  }
});

const responses = {
  "WordPress":"I have 5+ years experience building custom WordPress systems with plugins, APIs and scalable structures.",
  "PHP":"I build backend logic using PHP mainly within WordPress ecosystems.",
  "JavaScript":"I use JS for UI interactions and dynamic frontend behavior.",
  "REST API":"I connect external systems and automate workflows using APIs.",
  "UI/UX":"I design clean and conversion-focused interfaces.",
  "GitHub":"I manage projects and version control using GitHub.",
  "HubSpot":"I integrate CRM systems and lead flows.",
  "Zapier":"I automate workflows between tools.",
  "Make":"Advanced automation and API logic.",
  "Slack":"Structured communication and integrations."
};

const feed = document.getElementById("chatFeed");
const input = document.getElementById("chatInput");

function addMessage(text, type){
  const div = document.createElement("div");
  div.className = "ai-msg " + type;
  div.innerText = text;
  feed.appendChild(div);
  feed.scrollTop = feed.scrollHeight;
}

document.querySelectorAll(".ai-chip").forEach(btn=>{
  btn.onclick = ()=>{
    const key = btn.innerText;
    addMessage(key, "user");
    setTimeout(()=> addMessage(responses[key], ""), 400);
  }
});

document.getElementById("sendBtn").onclick = ()=>{
  const val = input.value;
  if(!val) return;
  addMessage(val, "user");
  setTimeout(()=> addMessage("This is a predefined AI-style response based on my tech stack.", ""), 400);
  input.value="";
};

(() => {
  const overlay = document.getElementById('storyOverlay');
  const modal = document.getElementById('storyModal');
  const closeBtn = document.getElementById('storyClose');
  const titleEl = document.getElementById('storyModalTitle');
  const descEl = document.getElementById('storyModalDesc');
  const imgEl = document.getElementById('storyModalImg');
  const ringEl = document.getElementById('storyModalRing');

  function openStory(card){
    titleEl.textContent = card.dataset.title || '';
    descEl.textContent = card.dataset.desc || '';
    imgEl.src = card.dataset.img || '';
    imgEl.alt = (card.dataset.title || '') + ' icon';
    ringEl.style.setProperty('--storyRing', card.dataset.ring || '#66f4ff');
    overlay.hidden = false;
    requestAnimationFrame(() => {
      overlay.classList.add('is-open');
      modal.classList.add('is-open');
      modal.setAttribute('aria-hidden','false');
      document.body.style.overflow = 'hidden';
    });
  }

  function closeStory(){
    overlay.classList.remove('is-open');
    modal.classList.remove('is-open');
    modal.setAttribute('aria-hidden','true');
    document.body.style.overflow = '';
    setTimeout(() => {
      if(!modal.classList.contains('is-open')) overlay.hidden = true;
    }, 360);
  }

  document.querySelectorAll('.story-item').forEach(card => {
    card.addEventListener('click', () => openStory(card));
  });

  closeBtn?.addEventListener('click', closeStory);
  overlay?.addEventListener('click', closeStory);
})();

(() => {
  const rail = document.getElementById('storyRail');
  const left = document.getElementById('storyNavLeft');
  const right = document.getElementById('storyNavRight');
  const step = 280;
  left?.addEventListener('click', () => rail?.scrollBy({left:-step, behavior:'smooth'}));
  right?.addEventListener('click', () => rail?.scrollBy({left:step, behavior:'smooth'}));
})();

(() => {
  const overlay = document.getElementById('storyOverlay');
  const modal = document.getElementById('storyModal');
  const closeBtn = document.getElementById('storyClose');
  const titleEl = document.getElementById('storyModalTitle');
  const leadEl = document.getElementById('storyModalLead');
  const bodyEl = document.getElementById('storyModalBody');
  const tagsEl = document.getElementById('storyModalTags');
  const imgEl = document.getElementById('storyModalImg');
  const ringEl = document.getElementById('storyModalRing');

  if (!overlay || !modal || !titleEl || !leadEl || !bodyEl || !tagsEl || !imgEl || !ringEl) return;


  const imgMapWordPress = document.querySelector('.story-item[data-title="WordPress"] img')?.src || '';
  const imgMapCSS = document.querySelector('.story-item[data-title="CSS"] img')?.src || '';
  const imgMapHTML = document.querySelector('.story-item[data-title="HTML"] img')?.src || '';
  const imgMapJavaScript = document.querySelector('.story-item[data-title="JavaScript"] img')?.src || '';
  const imgMapN8N = document.querySelector('.story-item[data-title="n8n"] img')?.src || '';
  const imgMapWooCommerce = document.querySelector('.story-item[data-title="WooCommerce"] img')?.src || '';

  const details = {
    'WordPress': { lead: 'Über 5 Jahre praktische Erfahrung in der Entwicklung von WordPress Systemen mit Fokus auf saubere Struktur, Skalierbarkeit und reale Anwendung.', body: 'Ich kombiniere WordPress gezielt mit Elementor, HTML, CSS, JavaScript und PHP, um visuell starke und technisch saubere Lösungen umzusetzen. Dabei entstehen modulare Systeme, die nicht nur gut aussehen, sondern auch wartbar, erweiterbar und langfristig nutzbar sind.', tags: [{ label: 'Elementor', ring: '#ff00cc', img: document.querySelector('.story-item[data-title="Elementor"] img')?.src || '' }, { label: 'WooCommerce', ring: '#7f54b3', img: imgMapWooCommerce }, { label: 'HTML', ring: '#e34f26', img: document.querySelector('.story-item[data-title="HTML"] img')?.src || '' }, { label: 'CSS', ring: '#264de4', img: document.querySelector('.story-item[data-title="CSS"] img')?.src || '' }, { label: 'JavaScript', ring: '#f7df1e', img: document.querySelector('.story-item[data-title="JavaScript"] img')?.src || '' }, { label: 'PHP', ring: '#777bb4', img: document.querySelector('.story-item[data-title="PHP"] img')?.src || '' }, { label: 'GitHub', ring: '#ffffff', img: document.querySelector('.story-item[data-title="GitHub"] img')?.src || '' }, { label: 'Zapier', ring: '#ff4f00', img: document.querySelector('.story-item[data-title="Zapier"] img')?.src || '' }, { label: 'Make', ring: '#6f5cff', img: document.querySelector('.story-item[data-title="Make"] img')?.src || '' }, { label: 'Slack', ring: '#4A154B', img: document.querySelector('.story-item[data-title="Slack"] img')?.src || '' }, { label: 'HubSpot', ring: '#ff7a59', img: document.querySelector('.story-item[data-title="HubSpot"] img')?.src || '' }, { label: 'n8n', ring: '#e84d7a', img: imgMapN8N }] },
    'Elementor': { lead: 'Effiziente Umsetzung moderner Interfaces mit Elementor als Teil eines strukturierten Frontend Workflows.', body: 'Ich nutze Elementor nicht als einfachen Page Builder, sondern in Kombination mit CSS, Layout Logik und WordPress Struktur, um präzise und responsive Designs umzusetzen. Der Fokus liegt auf klarer Nutzerführung, sauberer Darstellung und einer schnellen, flexiblen Umsetzung von Ideen.', tags: [{ label: 'WordPress', ring: '#21759b', img: imgMapWordPress }, { label: 'WooCommerce', ring: '#7f54b3', img: imgMapWooCommerce }, { label: 'HTML', ring: '#e34f26', img: imgMapHTML }, { label: 'CSS', ring: '#264de4', img: imgMapCSS }, { label: 'JavaScript', ring: '#f7df1e', img: imgMapJavaScript }] },
    'WooCommerce': { lead: 'WooCommerce nutze ich als strukturierte Commerce-Erweiterung innerhalb moderner WordPress Systeme   nicht als starres Shop-Plugin, sondern als flexible Basis für saubere Produktlogik und klare Nutzerführung.', body: 'Für mich ist WooCommerce dann stark, wenn Shop, Design und Technik sauber zusammenspielen. Ich kombiniere WooCommerce mit WordPress, HTML, CSS und JavaScript, um Produktseiten, Warenkorb-Logik, Checkout-Bereiche und individuelle Shop-Elemente präzise umzusetzen. Je nach Projekt kann auch GitHub sinnvoll sein, wenn Anpassungen strukturiert versioniert und sauber weiterentwickelt werden sollen.', tags: [{ label: 'WordPress', ring: '#21759b', img: imgMapWordPress }, { label: 'HTML', ring: '#e34f26', img: imgMapHTML }, { label: 'CSS', ring: '#264de4', img: imgMapCSS }, { label: 'JavaScript', ring: '#f7df1e', img: imgMapJavaScript }, { label: 'GitHub', ring: '#ffffff', img: document.querySelector('.story-item[data-title="GitHub"] img')?.src || '' }] },
    'API Integrationen': { lead: 'APIs nutze ich, um Websites mit externen Diensten, Datenquellen und Prozessen sauber zu verbinden.', body: 'Für mich sind API Integrationen dann stark, wenn sie im Hintergrund zuverlässig funktionieren und im Frontend trotzdem klar und einfach wirken. Es geht nicht um Technik um ihrer selbst willen, sondern um saubere Verbindungen zwischen Website, Tools, Daten und echten Abläufen.', tags: [{ label: 'Google Maps', ring: '#34a853', img: 'data:image/svg+xml;base64,' }, { label: 'OpenAI', ring: '#10a37f', img: 'data:image/svg+xml;base64,' }, { label: 'Gemini', ring: '#8e75ff', img: 'data:image/svg+xml;base64,' }, { label: 'Mistral AI', ring: '#ff8a00', img: 'data:image/svg+xml;base64,' }, { label: 'Mapbox', ring: '#d9d9d9', img: 'data:image/svg+xml;base64,' }, { label: 'Eventbrite', ring: '#ff8000', img: 'data:image/svg+xml;base64,' }, { label: 'Ticketmaster', ring: '#026cdf', img: 'data:image/svg+xml;base64,' }] },
    'API': { lead: 'Verbindung von Systemen durch stabile und praxisnahe API Integrationen.', body: 'Ich integriere externe Services in bestehende WordPress oder Websysteme, um Datenflüsse zu automatisieren und Funktionen gezielt zu erweitern. APIs wurden dabei real integriert und getestet, unter anderem mit Apple, Tesla, Google Places API, OpenAI, GPT 4, Gemini und Mistral AI. Wichtig ist für mich immer eine saubere Struktur, Wartbarkeit und sinnvolle Nutzung im echten Workflow.', tags: [{ label: 'Google Places API', ring: '#007bff', img: 'data:image/svg+xml;utf8,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2024%2024%22%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%223.2%22%20fill=%22rgba(255,255,255,0.9)%22/%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%227.2%22%20fill=%22none%22%20stroke=%22rgba(255,255,255,0.65)%22%20stroke-width=%221.4%22/%3E%3C/svg%3E' }, { label: 'OpenAI', ring: '#10a37f', img: 'data:image/svg+xml;base64,' }, { label: 'GPT 4', ring: '#10a37f', img: 'data:image/svg+xml;utf8,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2024%2024%22%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%223.2%22%20fill=%22rgba(255,255,255,0.9)%22/%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%227.2%22%20fill=%22none%22%20stroke=%22rgba(255,255,255,0.65)%22%20stroke-width=%221.4%22/%3E%3C/svg%3E' }, { label: 'Gemini', ring: '#8e75ff', img: 'data:image/svg+xml;base64,' }, { label: 'Mistral AI', ring: '#ff8a00', img: 'data:image/svg+xml;base64,' }] },
    'JavaScript': { lead: 'Dynamische Frontend Logik für interaktive und moderne Nutzererlebnisse.', body: 'Ich nutze JavaScript, um Interfaces lebendiger zu machen, Prozesse zu automatisieren und komplexe UI Verhalten umzusetzen. Der Fokus liegt auf Performance, sauberem Code und sinnvoller Integration ins Gesamtsystem.', tags: [{ label: 'HTML', ring: '#e34f26', img: document.querySelector('.story-item[data-title="HTML"] img')?.src || '' }, { label: 'CSS', ring: '#264de4', img: document.querySelector('.story-item[data-title="CSS"] img')?.src || '' }, { label: 'Elementor', ring: '#ff00cc', img: document.querySelector('.story-item[data-title="Elementor"] img')?.src || '' }, { label: 'WordPress', ring: '#21759b', img: document.querySelector('.story-item[data-title="WordPress"] img')?.src || '' }, { label: 'GitHub', ring: '#ffffff', img: document.querySelector('.story-item[data-title="GitHub"] img')?.src || '' }, { label: 'HubSpot', ring: '#ff7a59', img: document.querySelector('.story-item[data-title="HubSpot"] img')?.src || '' }, { label: 'n8n', ring: '#e84d7a', img: imgMapN8N }] },
    'HTML': { lead: 'Saubere semantische Struktur als Grundlage jeder Webanwendung.', body: 'Ich arbeite mit klarem, strukturiertem HTML, um stabile und zugängliche Layouts zu erstellen, die als Basis für Design und Funktion dienen. Eine gute Struktur ist für mich der erste Schritt zu einem hochwertigen Ergebnis.', tags: [{ label: 'CSS', ring: '#264de4', img: document.querySelector('.story-item[data-title="CSS"] img')?.src || '' }, { label: 'JavaScript', ring: '#f7df1e', img: document.querySelector('.story-item[data-title="JavaScript"] img')?.src || '' }, { label: 'Elementor', ring: '#ff00cc', img: document.querySelector('.story-item[data-title="Elementor"] img')?.src || '' }, { label: 'WordPress', ring: '#21759b', img: document.querySelector('.story-item[data-title="WordPress"] img')?.src || '' }, { label: 'GitHub', ring: '#ffffff', img: document.querySelector('.story-item[data-title="GitHub"] img')?.src || '' }, { label: 'HubSpot', ring: '#ff7a59', img: document.querySelector('.story-item[data-title="HubSpot"] img')?.src || '' }, { label: 'n8n', ring: '#e84d7a', img: imgMapN8N }] },
    'CSS': { lead: 'Visuelle Präzision und responsive Design Umsetzung auf allen Geräten.', body: 'Ich nutze CSS, um moderne Layouts, Animationen und saubere Darstellungen umzusetzen. Dabei achte ich auf Konsistenz, Wiederverwendbarkeit und klare Designsysteme, die auch langfristig stabil bleiben.', tags: [{ label: 'HTML', ring: '#e34f26', img: document.querySelector('.story-item[data-title="HTML"] img')?.src || '' }, { label: 'JavaScript', ring: '#f7df1e', img: document.querySelector('.story-item[data-title="JavaScript"] img')?.src || '' }, { label: 'Elementor', ring: '#ff00cc', img: document.querySelector('.story-item[data-title="Elementor"] img')?.src || '' }, { label: 'WordPress', ring: '#21759b', img: document.querySelector('.story-item[data-title="WordPress"] img')?.src || '' }, { label: 'GitHub', ring: '#ffffff', img: document.querySelector('.story-item[data-title="GitHub"] img')?.src || '' }, { label: 'HubSpot', ring: '#ff7a59', img: document.querySelector('.story-item[data-title="HubSpot"] img')?.src || '' }, { label: 'n8n', ring: '#e84d7a', img: imgMapN8N }] },
    'PHP': { lead: 'Backend Logik für WordPress und strukturierte serverseitige Erweiterungen.', body: 'Ich nutze PHP hauptsächlich innerhalb von WordPress Umgebungen, um Hooks, eigene Logik, Plugin Funktionen und stabile Backend Strukturen umzusetzen. Wichtig ist für mich dabei immer Lesbarkeit, Wartbarkeit und eine klare Systemlogik.', tags: [{ label: 'WordPress', ring: '#21759b', img: 'data:image/svg+xml;base64,' }, { label: 'Plugins', ring: '#ff66cc', img: 'data:image/png;base64,' }, { label: 'API Integrationen', ring: '#007bff', img: 'data:image/svg+xml;base64,' }] },
    'GitHub': { lead: 'GitHub nutze ich als technische Basis für saubere Versionierung, nachvollziehbare Änderungen und strukturierte Projektarbeit.', body: 'Für mich ist GitHub nicht nur ein Ort zum Ablegen von Code, sondern Teil einer klaren Arbeitsweise. Versionierung, saubere Commits und nachvollziehbare Entwicklung sorgen dafür, dass Änderungen kontrolliert, wartbar und teamfähig bleiben. Gerade im Zusammenspiel mit WordPress, JavaScript, Automationen und externen Tools macht das einen echten Unterschied.', tags: [{ label: 'WordPress', ring: '#21759b', img: document.querySelector('.story-item[data-title="WordPress"] img')?.src || '' }, { label: 'JavaScript', ring: '#f7df1e', img: imgMapJavaScript }, { label: 'Zapier', ring: '#ff4f00', img: document.querySelector('.story-item[data-title="Zapier"] img')?.src || '' }, { label: 'Make', ring: '#6f5cff', img: document.querySelector('.story-item[data-title="Make"] img')?.src || '' }, { label: 'n8n', ring: '#e84d7a', img: imgMapN8N }] },
    'HubSpot': { lead: 'CRM orientierte Prozesse und saubere Verbindung zwischen Website und Lead Logik.', body: 'Ich nutze HubSpot, um Website Prozesse, Lead Erfassung und CRM Orientierung sinnvoll miteinander zu verbinden. Dadurch entstehen klarere Conversion Abläufe und eine bessere technische Struktur für Marketing und Vertrieb.', tags: [{ label: 'WordPress', ring: '#21759b', img: document.querySelector('.story-item[data-title="WordPress"] img')?.src || '' }, { label: 'HTML', ring: '#e34f26', img: document.querySelector('.story-item[data-title="HTML"] img')?.src || '' }, { label: 'CSS', ring: '#264de4', img: document.querySelector('.story-item[data-title="CSS"] img')?.src || '' }, { label: 'JavaScript', ring: '#f7df1e', img: document.querySelector('.story-item[data-title="JavaScript"] img')?.src || '' }, { label: 'Zapier', ring: '#ff4f00', img: document.querySelector('.story-item[data-title="Zapier"] img')?.src || '' }, { label: 'Make', ring: '#6f5cff', img: document.querySelector('.story-item[data-title="Make"] img')?.src || '' }, { label: 'Slack', ring: '#4A154B', img: document.querySelector('.story-item[data-title="Slack"] img')?.src || '' }] },
    'Zapier': { lead: 'Automatisierung repetitiver Prozesse durch klar definierte Tool Verknüpfungen.', body: 'Mit Zapier automatisiere ich wiederkehrende Abläufe zwischen verschiedenen Diensten, damit Prozesse schneller, sauberer und mit weniger manuellem Aufwand laufen.', tags: [{ label: 'WordPress', ring: '#21759b', img: document.querySelector('.story-item[data-title="WordPress"] img')?.src || '' }, { label: 'HubSpot', ring: '#ff7a59', img: document.querySelector('.story-item[data-title="HubSpot"] img')?.src || '' }, { label: 'Slack', ring: '#4A154B', img: document.querySelector('.story-item[data-title="Slack"] img')?.src || '' }, { label: 'n8n', ring: '#e84d7a', img: imgMapN8N }] },
    'Make': { lead: 'Visuelle Automatisierung für komplexere Abläufe und API basierte Prozesslogik.', body: 'Ich nutze Make für flexiblere Automationen, bei denen mehrere Systeme, APIs und Bedingungen zusammenarbeiten. Dadurch lassen sich auch anspruchsvollere Prozessketten klar und steuerbar aufbauen.', tags: [{ label: 'WordPress', ring: '#21759b', img: document.querySelector('.story-item[data-title="WordPress"] img')?.src || '' }, { label: 'HubSpot', ring: '#ff7a59', img: document.querySelector('.story-item[data-title="HubSpot"] img')?.src || '' }, { label: 'Slack', ring: '#4A154B', img: document.querySelector('.story-item[data-title="Slack"] img')?.src || '' }, { label: 'n8n', ring: '#e84d7a', img: imgMapN8N }] },
    'n8n': { lead: 'n8n setze ich dort ein, wo Prozesse flexibel, sauber und nachvollziehbar automatisiert werden sollen.', body: 'Für mich ist n8n stark, wenn Formulare, APIs, Tools und interne Abläufe nicht nur verbunden werden, sondern als sauberes System zusammenarbeiten. Im Zusammenspiel mit WordPress, GitHub, Zapier oder Make lassen sich damit Prozesse aufbauen, die Daten automatisch weitergeben, manuelle Arbeit reduzieren und langfristig wartbar bleiben.', tags: [{ label: 'WordPress', ring: '#21759b', img: document.querySelector('.story-item[data-title="WordPress"] img')?.src || '' }, { label: 'GitHub', ring: '#ffffff', img: document.querySelector('.story-item[data-title="GitHub"] img')?.src || '' }, { label: 'Zapier', ring: '#ff4f00', img: document.querySelector('.story-item[data-title="Zapier"] img')?.src || '' }, { label: 'Make', ring: '#6f5cff', img: document.querySelector('.story-item[data-title="Make"] img')?.src || '' }] },
    'Slack': { lead: 'Strukturierte Kommunikation als Teil effizienter technischer Workflows.', body: 'Slack nutze ich im Zusammenspiel mit Projekten, Teams und Integrationen, um Kommunikation, Transparenz und operative Abläufe klarer zu organisieren.', tags: [{ label: 'WordPress', ring: '#21759b', img: document.querySelector('.story-item[data-title="WordPress"] img')?.src || '' }, { label: 'GitHub', ring: '#ffffff', img: document.querySelector('.story-item[data-title="GitHub"] img')?.src || '' }, { label: 'HubSpot', ring: '#ff7a59', img: document.querySelector('.story-item[data-title="HubSpot"] img')?.src || '' }, { label: 'Zapier', ring: '#ff4f00', img: document.querySelector('.story-item[data-title="Zapier"] img')?.src || '' }, { label: 'Make', ring: '#6f5cff', img: document.querySelector('.story-item[data-title="Make"] img')?.src || '' }] }
  };

  function renderTags(tags){
    tagsEl.innerHTML = '';
    (tags || []).forEach(tag => {
      const el = document.createElement('div');
      el.className = 'story-modal-tag';
      el.style.setProperty('--tagRing', tag.ring || '#66f4ff');
      el.innerHTML =
        '<span class="story-modal-tag-ring"><span class="story-modal-tag-core"><img src="' + (tag.img || '') + '" alt="' + (tag.label || '') + '"></span></span>' +
        '<span class="story-modal-tag-label">' + (tag.label || '') + '</span>';
      tagsEl.appendChild(el);
    });
  }

  function openStory(card){
    const rawTitle = card.dataset.title || '';
    const title = rawTitle === 'API' ? 'API Integrationen' : rawTitle;
    const desc = card.dataset.desc || '';
    const img = card.querySelector('img')?.src || card.dataset.img || '';

    let ring = card.dataset.ring || '#66f4ff';
    if (title === 'Elementor') ring = '#ff00cc';
    if (title === 'API Integrationen') ring = '#007bff';

    const content = details[title] || {
      lead: desc,
      body: '',
      tags: []
    };

    titleEl.textContent = title;
    leadEl.textContent = content.lead || '';
    bodyEl.textContent = content.body || '';
    renderTags(content.tags || []);
    imgEl.src = img;
    imgEl.alt = title ? `${title} icon` : 'Technology icon';
    ringEl.style.setProperty('--storyRing', ring);

    overlay.hidden = false;
    requestAnimationFrame(() => {
      overlay.classList.add('is-open');
      modal.classList.add('is-open');
      modal.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    });
  }

  function closeStory(){
    overlay.classList.remove('is-open');
    modal.classList.remove('is-open');
    modal.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
    setTimeout(() => {
      if (!modal.classList.contains('is-open')) overlay.hidden = true;
    }, 360);
  }

  document.querySelectorAll('.story-item').forEach(card => {
    card.onclick = () => openStory(card);
  });

  if (closeBtn) closeBtn.onclick = closeStory;
  if (overlay) overlay.onclick = closeStory;
})();

