(() => {
  const section = document.getElementById('why-websites');
  if (!section) return;

  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        section.classList.remove('is-visible');
        requestAnimationFrame(() => {
          requestAnimationFrame(() => section.classList.add('is-visible'));
        });
      } else {
        section.classList.remove('is-visible');
      }
    });
  }, {
    threshold: 0.32,
    rootMargin: '0px 0px -10% 0px'
  });

  observer.observe(section);
})();

(() => {
  const track = document.querySelector('#projects .appleflow-track');
  const cards = Array.from(document.querySelectorAll('#projects .appleflow-card'));
  const dots = Array.from(document.querySelectorAll('#projects .appleflow-dot'));
  const prev = document.querySelector('#projects .appleflow-nav-btn.is-prev');
  const next = document.querySelector('#projects .appleflow-nav-btn.is-next');
  if (!track || !cards.length || !dots.length) return;

  let current = 0;
  let raf = null;
  let lockScrollSyncUntil = 0;

  const wrap = (i) => ((i % cards.length) + cards.length) % cards.length;

  const update = (i) => {
    cards.forEach((card, index) => card.classList.toggle('is-active', index === i));
    dots.forEach((dot, index) => dot.classList.toggle('is-active', index === i));
    current = i;
  };

  const closestIndex = () => {
    const left = track.scrollLeft;
    let best = 0;
    let bestDistance = Infinity;

    cards.forEach((card, index) => {
      const distance = Math.abs(card.offsetLeft - left);
      if (distance < bestDistance) {
        bestDistance = distance;
        best = index;
      }
    });

    return best;
  };

  const goTo = (index) => {
    const safe = wrap(index);
    const isDesktop = window.matchMedia('(min-width: 769px)').matches;

    update(safe);

    if (isDesktop) {
      lockScrollSyncUntil = performance.now() + 420;
      track.scrollLeft = cards[safe].offsetLeft;
    } else {
      track.scrollTo({
        left: cards[safe].offsetLeft,
        behavior: 'smooth'
      });
    }
  };

  const sync = () => {
    if (performance.now() < lockScrollSyncUntil) return;

    if (raf) cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => {
      const nextIndex = closestIndex();
      if (nextIndex !== current) update(nextIndex);
    });
  };

  dots.forEach((dot, index) => {
    dot.addEventListener('click', (event) => {
      event.preventDefault();
      goTo(index);
    });
    dot.addEventListener('touchstart', (event) => {
      event.preventDefault();
      goTo(index);
    }, { passive: false });
  });

  prev?.addEventListener('click', (event) => {
    event.preventDefault();
    goTo(current - 1);
  });

  next?.addEventListener('click', (event) => {
    event.preventDefault();
    goTo(current + 1);
  });

  track.addEventListener('scroll', sync, { passive: true });
  window.addEventListener('resize', () => goTo(current));

  update(0);
})();

(() => {
  const tabsBar = document.querySelector('#expertise .expertise-tabs-bar');
  const tabs = Array.from(document.querySelectorAll('#expertise .expertise-tab'));
  const panels = Array.from(document.querySelectorAll('#expertise .expertise-panel'));
  if (!tabsBar || !tabs.length || !panels.length) return;

  let highlight = tabsBar.querySelector('.expertise-tab-highlight');
  if (!highlight) {
    highlight = document.createElement('div');
    highlight.className = 'expertise-tab-highlight';
    tabsBar.insertBefore(highlight, tabsBar.firstChild);
  }

  const moveHighlight = (tab, immediate = false) => {
    const x = tab.offsetLeft;
    const w = tab.offsetWidth;
    if (immediate) {
      const old = highlight.style.transition;
      highlight.style.transition = 'none';
      highlight.style.width = `${w}px`;
      highlight.style.transform = `translateX(${x}px)`;
      requestAnimationFrame(() => { highlight.style.transition = old || ''; });
    } else {
      highlight.style.width = `${w}px`;
      highlight.style.transform = `translateX(${x}px)`;
    }
  };

  const activate = (index, immediate = false) => {
    tabs.forEach((tab, i) => {
      const active = i === index;
      tab.classList.toggle('is-active', active);
      tab.setAttribute('aria-selected', active ? 'true' : 'false');
      if (active) moveHighlight(tab, immediate);
    });

    panels.forEach((panel, i) => {
      const active = i === index;
      if (active) {
        panel.hidden = false;
        panel.classList.add('is-entering');
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            panel.classList.add('is-active');
            panel.classList.remove('is-entering');
          });
        });
      } else {
        panel.classList.remove('is-active');
        panel.hidden = true;
        panel.classList.remove('is-entering');
      }
    });
  };

  tabs.forEach((tab, index) => {
    tab.addEventListener('click', () => activate(index));
  });

  window.addEventListener('resize', () => {
    const activeTab = tabs.find(t => t.classList.contains('is-active')) || tabs[0];
    moveHighlight(activeTab, true);
  });

  activate(0, true);
})();

